import type { FastifyInstance } from "fastify";

export async function projectsRoutes(app: FastifyInstance) {
  app.get("/projects", async (req) => {
    const { cursor, limit = 50 } = req.query as { cursor?: string; limit?: number };
    return { items: [], nextCursor: cursor ?? null, limit };
  });
}

import Fastify from "fastify";
import { projectsRoutes } from "./projects";

export const app = Fastify({ logger: true });
app.register(projectsRoutes, { prefix: "/v2" });

app.setErrorHandler((err, _req, reply) => {
  if (err.statusCode === 429) {
    reply.header("Retry-After", "30");
  }
  reply.status(err.statusCode ?? 500).send({ error: err.message });
});

const REFRESH_MARGIN_MS = 5 * 60 * 1000;

export function shouldRefresh(expiresAt: number, now = Date.now()) {
  return expiresAt - now < REFRESH_MARGIN_MS;
}

export type UsageLine = { metric: string; quantity: number; unitPriceCents: number };

export function buildInvoice(lines: UsageLine[]) {
  const items = lines.map((l) => ({ ...l, totalCents: l.quantity * l.unitPriceCents }));
  return { items, totalCents: items.reduce((s, i) => s + i.totalCents, 0) };
}

const warmCache = new Map<string, number>();

export function warmTenantIndex(tenantId: string) {
  if (warmCache.has(tenantId)) return warmCache.get(tenantId)!;
  const builtAt = Date.now();
  warmCache.set(tenantId, builtAt);
  return builtAt;
}
